//
//  Typeface.swift
//
//  The stroke typeface, and the math that sizes one glyph.
//
//  How the writing effect works: a letter here is not an outline, it is the
//  path a pen took. Each glyph is a list of strokes, each stroke a list of
//  points in drawing order. To show a finished letter you draw the whole
//  path; to animate it you draw the path from the start up to some length.
//
//  `typeface.json` is generated by `ios/scripts/build-typeface.mjs` from a
//  single-line SVG font (EMS Allure: the script Allura, traced as pen
//  strokes for plotters). Coordinates are font units, 1000 per em, with y
//  pointing down and the origin on the baseline at the left of the glyph's
//  advance box. Letters in a connected script start left of their origin and
//  end past their advance on purpose: that is how they join their neighbours.
//

import SwiftUI

struct RawGlyph: Decodable {
    /// Advance width: how far the pen moves right before the next letter.
    let adv: Double
    /// Strokes, each a flat list: x0, y0, x1, y1, ...
    let s: [[Double]]
}

struct TypefaceData: Decodable {
    let name: String
    let upm: Double
    let ascent: Double
    let descent: Double
    let xHeight: Double
    let capHeight: Double
    let glyphs: [String: RawGlyph]
}

/// One stroke, sized for a font size. Points are relative to the glyph origin (pen start, baseline).
struct ScaledStroke {
    let path: Path
    let length: CGFloat
}

struct ScaledGlyph {
    /// Advance width in points.
    let advance: CGFloat
    let strokes: [ScaledStroke]
    /// Sum of stroke lengths in points.
    let totalLength: CGFloat
    /// Sum of stroke lengths in font units. Writing speed is "font units per second".
    let unitLength: CGFloat
}

@MainActor
final class Typeface {
    static let shared = Typeface()

    /// How far the baseline sits below the top of a glyph box, in ems. Swashes reach a full em up.
    static let baselineEm: CGFloat = 1.0
    /// Glyph box height in ems: room for the tallest flourish above and the deepest below.
    static let boxEm: CGFloat = 1.45

    let data: TypefaceData
    private var cache: [String: ScaledGlyph] = [:]

    private init() {
        guard let url = Bundle.main.url(forResource: "typeface", withExtension: "json"),
              let bytes = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(TypefaceData.self, from: bytes)
        else {
            preconditionFailure("typeface.json is missing from the app bundle")
        }
        data = decoded
    }

    func raw(_ character: Character) -> RawGlyph? {
        data.glyphs[String(character)]
    }

    var spaceAdvance: Double {
        data.glyphs[" "]?.adv ?? 378
    }

    /// Scales a glyph to a font size (the em), exactly like a normal font would.
    func scaled(_ character: Character, size: CGFloat) -> ScaledGlyph? {
        let key = "\(character)@\(size)"
        if let hit = cache[key] { return hit }
        guard let glyph = raw(character) else { return nil }

        let scale = size / CGFloat(data.upm)
        var totalLength: CGFloat = 0
        let strokes: [ScaledStroke] = glyph.s.map { flat in
            var path = Path()
            var length: CGFloat = 0
            var previous: CGPoint?
            var i = 0
            while i + 1 < flat.count {
                let point = CGPoint(x: CGFloat(flat[i]) * scale, y: CGFloat(flat[i + 1]) * scale)
                if let previous {
                    path.addLine(to: point)
                    length += hypot(point.x - previous.x, point.y - previous.y)
                } else {
                    path.move(to: point)
                }
                previous = point
                i += 2
            }
            totalLength += length
            return ScaledStroke(path: path, length: length)
        }

        let result = ScaledGlyph(
            advance: CGFloat(glyph.adv) * scale,
            strokes: strokes,
            totalLength: totalLength,
            unitLength: totalLength / scale
        )
        cache[key] = result
        return result
    }
}
